CREATE OR REPLACE FUNCTION public.fn_submit_assessment(p_token text, p_responses text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ DECLARE v_invitation record; v_cycle record; v_response jsonb; v_count int; v_required_count int; v_submitted_required_count int; BEGIN IF p_token IS NULL OR length(p_token) < 16 OR p_responses IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_request'); END IF; SELECT ai.id, ai.cycle_id, ai.tenant_id, ai.used_at, ai.expires_at INTO v_invitation FROM public.assessment_invitations ai WHERE ai.token = p_token FOR UPDATE; IF v_invitation IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_or_expired'); END IF; IF v_invitation.used_at IS NOT NULL THEN RETURN jsonb_build_object('success', false, 'error', 'already_submitted'); END IF; IF v_invitation.expires_at IS NOT NULL AND v_invitation.expires_at <= now() THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_or_expired'); END IF; SELECT ac.id, ac.status, ac.ends_at, ac.questionnaire_template_id INTO v_cycle FROM public.assessment_cycles ac WHERE ac.id = v_invitation.cycle_id AND ac.deleted_at IS NULL; IF v_cycle IS NULL OR v_cycle.status <> 'active' OR v_cycle.ends_at <= now() THEN RETURN jsonb_build_object('success', false, 'error', 'cycle_not_active'); END IF; BEGIN v_response := p_responses::jsonb; EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_payload'); END; IF jsonb_typeof(v_response) <> 'array' OR jsonb_array_length(v_response) = 0 THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_payload'); END IF; IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_response) x WHERE jsonb_typeof(x) <> 'object' OR NOT (x ? 'item_id') OR NOT (x ? 'value') OR jsonb_typeof(x->'item_id') <> 'string' OR jsonb_typeof(x->'value') <> 'number') THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_payload'); END IF; BEGIN IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_response) x WHERE (x->>'value')::int < 1 OR (x->>'value')::int > 5) THEN RETURN jsonb_build_object('success', false, 'error', 'value_out_of_range'); END IF; EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_payload'); END; IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_response) x GROUP BY x->>'item_id' HAVING count(*) > 1) THEN RETURN jsonb_build_object('success', false, 'error', 'duplicate_item'); END IF; BEGIN IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_response) x LEFT JOIN public.questionnaire_items qi ON qi.id = (x->>'item_id')::uuid LEFT JOIN public.questionnaire_sections qs ON qs.id = qi.section_id WHERE qi.id IS NULL OR qs.template_id <> v_cycle.questionnaire_template_id) THEN RETURN jsonb_build_object('success', false, 'error', 'unknown_item'); END IF; EXCEPTION WHEN invalid_text_representation THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_payload'); END; SELECT count(*) INTO v_required_count FROM public.questionnaire_items qi JOIN public.questionnaire_sections qs ON qs.id = qi.section_id WHERE qs.template_id = v_cycle.questionnaire_template_id AND qi.required IS TRUE; SELECT count(*) INTO v_submitted_required_count FROM jsonb_array_elements(v_response) x JOIN public.questionnaire_items qi ON qi.id = (x->>'item_id')::uuid WHERE qi.required IS TRUE; IF v_submitted_required_count <> v_required_count THEN RETURN jsonb_build_object('success', false, 'error', 'missing_required_items'); END IF; INSERT INTO public.assessment_responses (invitation_id, cycle_id, tenant_id, item_id, value) SELECT v_invitation.id, v_invitation.cycle_id, v_invitation.tenant_id, (x->>'item_id')::uuid, (x->>'value')::int FROM jsonb_array_elements(v_response) x; GET DIAGNOSTICS v_count = ROW_COUNT; UPDATE public.assessment_invitations SET used_at = now() WHERE id = v_invitation.id AND used_at IS NULL; RETURN jsonb_build_object('success', true, 'items_recorded', v_count); END; $function$;
REVOKE EXECUTE ON FUNCTION public.fn_submit_assessment(text, text) FROM PUBLIC, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_submit_assessment(text, text) TO anon;
